<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides member skill behavior within the WorkIntel application. */ class MemberSkill extends Model{protected $fillable=['workspace_id','member_id','skill_id','proficiency','target_proficiency','assessed_by','assessed_at','evidence'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['assessed_at'=>'datetime'];}/** Handles the skill operation for the current WorkIntel workflow. */ public function skill():BelongsTo{return $this->belongsTo(Skill::class,'skill_id');}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}}
